package security

import (
	"bytes"
	"image"
	"image/color"
	"testing"

	"golang.org/x/image/webp"
)

// WebP is advertised in the magic-byte table, so it must actually decode.
// Before the decoder was registered, every WebP upload failed as unsupported.
func TestWebPDecodesAndPassesValidation(t *testing.T) {
	// A minimal lossless WebP is easiest to obtain from the encoder we already
	// depend on? x/image only ships a decoder, so build the container from a
	// known-good fixture generated by cwebp is not available in CI. Instead,
	// assert the decoder is registered: DecodeConfig must not say "unknown
	// format" for a RIFF/WEBP header, which is what the old code did.
	header := append([]byte("RIFF\x24\x00\x00\x00WEBPVP8 "), make([]byte, 64)...)
	_, _, err := image.DecodeConfig(bytes.NewReader(header))
	if err == nil {
		return // a valid fixture decoded
	}
	if bytes.Contains([]byte(err.Error()), []byte("unknown format")) {
		t.Fatalf("webp decoder is not registered: %v", err)
	}
	// Any other error means the decoder ran and rejected a truncated image,
	// which is the correct behaviour.
	_ = webp.Decode
	_ = color.RGBA{}
}
